    fn get_document_initial_targets(
    ) -> &'static [::sce_rust_runtime::EntryTarget<Self::State, Self::History>] {
        &[::sce_rust_runtime::EntryTarget::State(
            StatechartHostInvokerState::Invoking,
        )]
    }

